// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    function setUp() public { c = new GameItems(address(this), address(this)); }

    function testFuzz_property(address account, uint256 id) public {

        bool ok;
        try c.balanceOf(account, id) returns (uint256) {
            ok = true;
        } catch {
            ok = false;
        }

        if (account == address(0)) {
            assertTrue(!ok);
        } else {
            assertTrue(ok);
        }
    }
}
